package com.mockarena.question.application;
import com.mockarena.question.api.QuestionCandidateContentDtos.*; import com.mockarena.question.domain.*; import com.mockarena.question.infrastructure.persistence.HistoricalQuestionVersionGenericMetadataRepository; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*;
@Service public class QuestionCandidateContentService {
 private final QuestionVersionRepository versions; private final HistoricalQuestionVersionGenericMetadataRepository historicalMetadata; public QuestionCandidateContentService(QuestionVersionRepository versions,HistoricalQuestionVersionGenericMetadataRepository historicalMetadata){this.versions=versions;this.historicalMetadata=historicalMetadata;}
 @Transactional(readOnly=true) public List<Entry> resolve(List<UUID> ids){ Map<UUID,QuestionVersion> found=new HashMap<>(); versions.findAllById(ids).forEach(v->found.put(v.id(),v)); Map<UUID,HistoricalQuestionVersionGenericMetadataRepository.Metadata> historical=historicalMetadata.findByQuestionVersionIds(ids); return ids.stream().map(id->{QuestionVersion v=Optional.ofNullable(found.get(id)).orElseThrow(()->new NoSuchElementException("Question version not found")); if(v.status()!=QuestionVersionStatus.PUBLISHED&&v.status()!=QuestionVersionStatus.RETIRED)throw new NoSuchElementException("Question version not deliverable"); HistoricalQuestionVersionGenericMetadataRepository.Metadata metadata=historical.get(v.id()); return new Entry(v.questionId(),v.id(),metadata==null?v.questionTypeCode():metadata.questionTypeCode(),v.title(),v.prompt(),v.options().stream().map(o->new Option(o.id(),o.text())).toList(),v.constraintsText(),v.examples(),metadata==null?v.programmingLanguages():metadata.programmingLanguages());}).toList(); }
}
